// On-demand, data-free checks; optional reference JSON generated by the R script.
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const context={};vm.createContext(context);
vm.runInContext(fs.readFileSync(new URL('estimate_correlation_clustering.js',import.meta.url),'utf8'),context);
const cluster=context.clusterEstimateCorrelations;
const bank={featureIndices:Array.from({length:19},(_,i)=>i),correlations:[]};
for(let i=0;i<19;i++)for(let j=i+1;j<19;j++)bank.correlations.push(i===18||j===18?-.8:Math.floor(i/6)===Math.floor(j/6)?.94-(i+j)*.00001:.05+(i+j)*.00001);
const before=JSON.stringify(bank),fit=cluster(bank,{minSize:5,deepSplit:1});
assert.equal(JSON.stringify(bank),before,'Clustering must not mutate correlations');
for(let i=0;i<18;i++)for(let j=0;j<18;j++)assert.equal(fit.labels[i]===fit.labels[j],Math.floor(i/6)===Math.floor(j/6));
assert.equal(fit.labels[18],0,'Isolated field stays unassigned');
assert.equal(new Set(fit.order).size,19);
assert.equal(fit.linkage.length,18);
assert(cluster(bank,{minSize:30,deepSplit:1}).labels.every(x=>x===0));
assert.throws(()=>cluster(bank,{minSize:1,deepSplit:1}),/Minimum/);
assert.throws(()=>cluster(bank,{minSize:5,deepSplit:5}),/sensitivity/);
assert.deepEqual(Array.from(cluster({featureIndices:[],correlations:[]},{minSize:5,deepSplit:1}).labels),[]);
assert.deepEqual(Array.from(cluster({featureIndices:[0],correlations:[]},{minSize:5,deepSplit:1}).labels),[0]);
if(process.argv[2]==='--tree'){
 const bank=JSON.parse(fs.readFileSync(process.argv[3]));
 fs.writeFileSync(process.argv[4],JSON.stringify(cluster(bank,{minSize:5,deepSplit:1})));
 console.log('Wrote browser hierarchy for a shared-tree reference check.');process.exit(0);
}
let comparisons=0;
for(const filename of process.argv.slice(2)){
 const reference=JSON.parse(fs.readFileSync(filename));
 for(const {bank,cases} of reference.examples||reference)for(const expected of cases){
  const actual=cluster(bank,expected).labels;
  for(let i=0;i<actual.length;i++){
   assert.equal(!actual[i],!expected.labels[i],`${filename}: unassigned field ${i}, size ${expected.minSize}, split ${expected.deepSplit}`);
   for(let j=0;j<i;j++)assert.equal(actual[i]===actual[j],expected.labels[i]===expected.labels[j],`${filename}: pair ${i}/${j}, size ${expected.minSize}, split ${expected.deepSplit}`);
  }comparisons++;
 }
}
console.log(`PASS: adaptive clusters, unassigned fields, parameter bounds, input preservation; ${comparisons} optional reference partitions.`);
